create table public.reports (id bigint generated by default as identity primary key, title text not null check (char_length(title) between 3 and 150), area text not null, place text not null, kind text not null, status text not null check (status in ('Needs attention','Work underway','Resolved')), author text not null default 'Neighbour', reputation integer not null default 0, lng double precision not null, lat double precision not null, photo boolean not null default false, source text not null default 'Resident report', user_id uuid not null default auth.uid(), created_at timestamptz not null default now());
create table public.comments (id bigint generated by default as identity primary key, report_id bigint not null references public.reports(id) on delete cascade, parent_id bigint references public.comments(id) on delete cascade, author text not null default 'Neighbour', text text not null check (char_length(text) between 1 and 500), user_id uuid not null default auth.uid(), created_at timestamptz not null default now());
create table public.report_votes (report_id bigint not null references public.reports(id) on delete cascade, user_id uuid not null default auth.uid(), value smallint not null check (value in (-1,1)), primary key (report_id,user_id));
create table public.comment_votes (comment_id bigint not null references public.comments(id) on delete cascade, user_id uuid not null default auth.uid(), value smallint not null check (value in (-1,1)), primary key (comment_id,user_id));
create table public.source_links (id bigint generated by default as identity primary key, zone text not null, label text not null check (char_length(label) between 1 and 100), url text not null check (url ~ '^https?://'), user_id uuid not null default auth.uid(), created_at timestamptz not null default now());
alter table public.reports enable row level security; alter table public.comments enable row level security; alter table public.report_votes enable row level security; alter table public.comment_votes enable row level security; alter table public.source_links enable row level security;
create policy "public reads reports" on public.reports for select using (true); create policy "anonymous users add reports" on public.reports for insert to authenticated with check (auth.uid() = user_id);
create policy "public reads comments" on public.comments for select using (true); create policy "anonymous users add comments" on public.comments for insert to authenticated with check (auth.uid() = user_id);
create policy "users read own report votes" on public.report_votes for select to authenticated using (auth.uid() = user_id); create policy "users add own report votes" on public.report_votes for insert to authenticated with check (auth.uid() = user_id); create policy "users update own report votes" on public.report_votes for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "users delete own report votes" on public.report_votes for delete to authenticated using (auth.uid() = user_id);
create policy "users read own comment votes" on public.comment_votes for select to authenticated using (auth.uid() = user_id); create policy "users add own comment votes" on public.comment_votes for insert to authenticated with check (auth.uid() = user_id); create policy "users update own comment votes" on public.comment_votes for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "users delete own comment votes" on public.comment_votes for delete to authenticated using (auth.uid() = user_id);
create policy "public reads links" on public.source_links for select using (true); create policy "anonymous users add links" on public.source_links for insert to authenticated with check (auth.uid() = user_id);
create view public.report_summaries as select r.*, coalesce((select sum(value) from public.report_votes v where v.report_id=r.id),0)::int as vote_score from public.reports r;
create view public.comment_summaries as select c.*, coalesce((select sum(value) from public.comment_votes v where v.comment_id=c.id),0)::int as vote_score from public.comments c;
grant select on public.report_summaries, public.comment_summaries to anon, authenticated;
